    def test_nodes_in_registration_order_with_fixed_keys(self) -> None:
        a = self._create("a", DIGEST_A)
        b = self._create("b", DIGEST_B)

        status, _h, body = call_json("GET", "/graph")
        self.assertEqual(status, "200 OK")
